import type {HandoffScope} from './cashier-handoff';
export type FinancialAccounts=Record<'receivable'|'prepayment'|'security'|'offset',string>;
export type FinancialPostingSelection={scope:HandoffScope;batch:string;period:string;accounts:FinancialAccounts};
const categories=['receivable','prepayment','security'] as const;
const uuid=(v:unknown):v is string=>typeof v==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(v);
function object(v:unknown){if(!v||typeof v!=='object'||Array.isArray(v))throw Error('Invalid financial posting data.');return v as Record<string,unknown>}
export function readFinancialPostingReview(value:unknown,s:FinancialPostingSelection){
 const v=object(value),period=object(v.period),mapping=object(v.account_mapping),totals=object(v.source_totals);
 if(![s.scope.tenant,s.scope.property,s.scope.actor,s.batch,s.period,...Object.values(s.accounts)].every(uuid)||new Set(Object.values(s.accounts)).size!==4||v.schema_version!==1||v.tenant_id!==s.scope.tenant||v.property_id!==s.scope.property||v.actor_id!==s.scope.actor||v.batch_id!==s.batch||v.financial_records_written!==false||period.id!==s.period||period.closed!==false||typeof v.cutover_date!=='string'||typeof period.starts_on!=='string'||typeof period.ends_before!=='string'||v.cutover_date<period.starts_on||v.cutover_date>=period.ends_before||typeof v.payload_sha256!=='string'||!/^[0-9a-f]{64}$/.test(v.payload_sha256)||!Array.isArray(v.accounts)||v.accounts.length!==4||!Array.isArray(v.rows)||v.rows.length<1||v.rows.length>500)throw Error('Posting review does not match the selected batch and period.');
 for(const category of [...categories,'offset'] as const){const account=v.accounts.map(object).find(a=>a.id===s.accounts[category]);if(mapping[category]!==s.accounts[category]||!account||account.tenant_id!==s.scope.tenant||account.property_id!==s.scope.property||account.active!==true||account.kind!==(category==='receivable'?'asset':category==='offset'?'equity':'liability')||typeof account.name!=='string')throw Error('Posting accounts do not match the selected categories.');}
 const sums={receivable:BigInt(0),prepayment:BigInt(0),security:BigInt(0)},ids=new Set<string>(),sources=new Set<string>();
 const rows=v.rows.map(raw=>{const r=object(raw);if(!uuid(r.opening_id)||!uuid(r.reservation_id)||ids.has(r.opening_id)||typeof r.source_item_id!=='string'||!r.source_item_id||sources.has(r.source_item_id)||typeof r.category!=='string'||!categories.includes(r.category as typeof categories[number])||typeof r.amount_minor!=='string'||!/^[1-9][0-9]{0,11}$/.test(r.amount_minor)||r.currency!=='USD'||typeof r.source_reference!=='string')throw Error('Invalid opening item in posting review.');ids.add(r.opening_id);sources.add(r.source_item_id);const category=r.category as typeof categories[number];sums[category]+=BigInt(r.amount_minor);const folio=object(object(r.destination_state).folio_balance);if(folio.reservation_id!==r.reservation_id||typeof folio.available!=='boolean')throw Error('Invalid destination folio review.');let destinationBalance:string|null=null;if(folio.available){const balance=object(folio.totals).balance_minor;if(typeof balance!=='number'||!Number.isSafeInteger(balance))throw Error('Invalid destination folio amount.');destinationBalance=String(balance)}return {id:r.opening_id,source:r.source_item_id,category,amount:r.amount_minor,reference:r.source_reference,reservation:r.reservation_id,destinationBalance};});
 for(const category of categories)if(totals[category]!==sums[category].toString())throw Error('Posting items do not match source control totals.');
 return {raw:v,rows,totals:sums,cutover:v.cutover_date};
}
export function readFinancialCommit(value:unknown,request:{id:string;selection:FinancialPostingSelection;review:unknown}){
 const reviewed=readFinancialPostingReview(request.review,request.selection),v=object(value),s=request.selection.scope;
 if(v.schema_version!==1||v.tenant_id!==s.tenant||v.property_id!==s.property||v.actor_id!==s.actor||v.request_id!==request.id||v.batch_id!==request.selection.batch||v.status!=='committed'||typeof v.replayed!=='boolean'||!Array.isArray(v.openings)||v.openings.length!==reviewed.rows.length)throw Error('Migration receipt does not match this request.');
 const journals=new Set<string>();v.openings.forEach((raw,index)=>{const row=object(raw);if(row.opening_id!==reviewed.rows[index].id||row.source_item_id!==reviewed.rows[index].source||!uuid(row.journal_id)||journals.has(row.journal_id))throw Error('Migration receipt does not match reviewed openings.');journals.add(row.journal_id)});
 for(const category of categories)if(object(v.source_totals)[category]!==reviewed.totals[category].toString())throw Error('Migration receipt totals differ from the review.');return v;
}
